-- end


function UI_Inspect:Start()
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ==============================
    self.ButtonClose.onClick:AddListener( Bind(self, self.OnPressCloseButton) )

    self.rootAnimation = KTool.GetComponent( self.Root.gameObject, typeof(Animation))
    assert( isNotNull(self.rootAnimation) )


    KTool.SetActive( self.ImgBlack.gameObject, false )
    KTool.SetActive( self.Root.gameObject, false )
    self._openState = OpenState.Closed



    currentInstance = self
end



function UI_Inspect:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = nil

    currentInstance = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

