function UI_Inspect.Instance()
    if isNull(currentInstance) then 
        printError("koko - UI_Inspect currentInstance is nil")
    end 
    return currentInstance
end


function UI_Inspect:GetOpenState()
    return self._openState
end 



function UI_Inspect:Update()
    if DreamSpaceStates.isWindowsPlatform == true and Input.GetKeyUp(KeyboardInfo.InspectKey) then 
        print("koko - 按下 R - " )
        self:Hide()
    end 

end



function UI_Inspect:Show( txtTitle_, txtContent_ )
    print("koko - UI_Inspect - Show ")
    if self._openState ~= OpenState.Closed then 
        return 
    end 
    
    if DreamSpaceStates.isWindowsPlatform == true then 
        -- pc 端要处理 子页面互斥:
        if DreamSpaceStates.IsSubPanelFreeInPC() == true and DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.None then
            DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.InspectPanel   
            self:__Show( txtTitle_, txtContent_ )
        end
    else
        self:__Show( txtTitle_, txtContent_ )        
    end
end


function UI_Inspect:__Show( txtTitle_, txtContent_ )
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = cs_coroutine.start(function()

        self._openState = OpenState.Opening

        DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Lock ) -- 希望禁止玩家输入
    
        KTool.SetActive( self.Root.gameObject, true )
        KTool.SetActive( self.PcClose.gameObject, DreamSpaceStates.isWindowsPlatform == true )
        KTool.SetActive( self.ButtonClose.gameObject, DreamSpaceStates.isWindowsPlatform == false )

        -- 关闭 主UI 界面:
        local uiMain_OnOff = UIMain_OnOff.Instance()
        if isNotNull(uiMain_OnOff) then 
            uiMain_OnOff:Hide()
        end 

        if type(txtTitle_) == "string" then 
            self.TxtTitle.text = txtTitle_
        end 

        if type(txtContent_) == "string" then 
            self.TxtContent.text = txtContent_
        end 


        coroutine.yield(Yielders.EndOfFrame)
        while self.rootAnimation.isPlaying == true and self.rootAnimation.clip.name == animationStr_entry do 
            coroutine.yield(Yielders.EndOfFrame)
        end 

        self._openState = OpenState.Opened   
        
        
    end) 
end



function UI_Inspect:Hide() 
    print("koko - UI_Inspect - Hide ")
    if self._openState ~= OpenState.Opened  then 
        return
    end 

    if DreamSpaceStates.isWindowsPlatform == true then 
        -- pc 端要处理 子页面互斥:
        if DreamSpaceStates.IsSubPanelFreeInPC() == true and DreamSpaceStates.currentOpenPanelTypeInPC == DreamSpaceStates.CurrentOpenPanelTypeInPC.InspectPanel then 
            DreamSpaceStates.currentOpenPanelTypeInPC = DreamSpaceStates.CurrentOpenPanelTypeInPC.None    
            self:__Hide()
        end
    else 
        self:__Hide()
    end
end


function UI_Inspect:__Hide() 
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = cs_coroutine.start(function()

        self._openState = OpenState.Closing

        self.rootAnimation:Play( animationStr_exit )

        coroutine.yield(Yielders.EndOfFrame)
        while self.rootAnimation.isPlaying == true and self.rootAnimation.clip.name == animationStr_exit do 
            coroutine.yield(Yielders.EndOfFrame)
        end 

        -- 开启 主UI 界面:
        local uiMain_OnOff = UIMain_OnOff.Instance()
        if isNotNull(uiMain_OnOff) then 
            uiMain_OnOff:Show()
        end 


        KTool.SetActive( self.Root.gameObject, false )

        DreamSpaceStates.LockInput_ByCount( DreamSpaceStates.InputLockState.Unlock ) -- 解除禁止:玩家输入

        self._openState = OpenState.Closed

    end) 
end







function UI_Inspect:OnPressCloseButton()
    print( "koko 按下 close 按钮")
    self:Hide()
end





return UI_Inspect

